INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Einwandbehandlung nur für den Vertrieb relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IT-Projekte"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Einwandbehandlung?', 3, '[{"text": "Kundenzufriedenheit sichern", "correct": true, "because": "Bedenken klären"}, {"text": "Kosten erhöhen", "correct": false, "because": "Nicht Ziel"}, {"text": "Hardware optimieren", "correct": false, "because": "Technischer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fähigkeiten sind für die Einwandbehandlung wichtig?', 5, '[{"text": "Kommunikation", "correct": true, "because": "Klarheit schaffen"}, {"text": "Empathie", "correct": true, "because": "Kunden verstehen"}, {"text": "Hardware-Kenntnisse", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einwandbehandlung klärt Bedenken. b) Sie ist nur für Kunden relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Einwandbehandlung?', 4, '[{"text": "Kundenbedenken", "correct": false, "because": "Kern der Aufgabe"}, {"text": "Lösungsvorschläge", "correct": false, "because": "Überzeugung nötig"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Einwandbehandlung technische Kenntnisse erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "IT-Kontext"}, {"text": "Nein", "correct": false, "because": "Technisches Wissen hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wird oft in der Einwandbehandlung genutzt?', 3, '[{"text": "Aktives Zuhören", "correct": true, "because": "Bedenken verstehen"}, {"text": "Code-Debugging", "correct": false, "because": "Technischer Fokus"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Einwandbehandlung?', 5, '[{"text": "Einwand anhören", "correct": true, "because": "Verständnis schaffen"}, {"text": "Lösung anbieten", "correct": true, "because": "Problem lösen"}, {"text": "Einwand ignorieren", "correct": false, "because": "Ineffektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Einwandbehandlung verbessert Kommunikation. b) Sie ist nur schriftlich möglich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch mündlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Einwandbehandlung?', 4, '[{"text": "Verständnis", "correct": false, "because": "Kundenbedenken"}, {"text": "Argumente", "correct": false, "because": "Überzeugung nötig"}, {"text": "Papierhandbücher", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Einwandbehandlung nur für den Support?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Projektmanagement"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Situationen erfordern Einwandbehandlung?', 4, '[{"text": "Kundenbeschwerden", "correct": true, "because": "Unzufriedenheit klären"}, {"text": "Projektverzögerungen", "correct": true, "because": "Bedenken adressieren"}, {"text": "Hardware-Design", "correct": false, "because": "Technischer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Einwandbehandlung Zeitverschwendung ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Vertrauen aufbauen"}, {"text": "Ja", "correct": false, "because": "Effektiv bei Konflikten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einwandbehandlung?', 3, '[{"text": "Kundenverständnis", "correct": true, "because": "Bedenken klären"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einwandbehandlung fördert Vertrauen. b) Sie ist nur für externe Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Einwandbehandlung?', 5, '[{"text": "Bessere Kundenbindung", "correct": true, "because": "Vertrauen stärken"}, {"text": "Konfliktlösung", "correct": true, "because": "Probleme klären"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Einwandbehandlung unwichtig?', 3, '[{"text": "Klarheit", "correct": false, "because": "Überzeugung nötig"}, {"text": "Lösungsorientierung", "correct": false, "because": "Ziel der Behandlung"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Einwandbehandlung Projekte verzögern?', 3, '[{"text": "Nein", "correct": true, "because": "Klärung hilft"}, {"text": "Ja", "correct": false, "because": "Effizienz steigern"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Einwandbehandlung Schulung erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "Fähigkeiten nötig"}, {"text": "Nein", "correct": false, "because": "Training hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die Einwandbehandlung zentral?', 4, '[{"text": "Kundenorientierung", "correct": true, "because": "Bedenken adressieren"}, {"text": "Ignorieren von Einwänden", "correct": false, "because": "Ineffektiv"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}]');
